package com.bank.career;

import com.bank.career.model.CareerMove;
import com.bank.career.service.ReasonClassifier;
import java.util.logging.*;

// Runnable demo: classify "why are you leaving" reasons as forward-looking or grievance.
public class MoveDemo {
    private static final Logger log = Logger.getLogger("Career");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        ReasonClassifier classifier = new ReasonClassifier(log);

        // Weak answer — grievance about the current company.
        CareerMove weak = new CareerMove(
            "Backend Engineer (monolith)",
            "The code was a mess and my manager never listened to me.",
            "Any new job");
        classifier.evaluate(weak);

        // Strong answer — forward-looking growth toward a specific role.
        CareerMove strong = new CareerMove(
            "Backend Engineer (monolith)",
            "I have taken the transfer service as far as my current scope allows; "
              + "I want to own an event-driven fraud platform end to end.",
            "Senior Engineer, real-time fraud detection");
        classifier.evaluate(strong);
    }
}
